<?php require __DIR__.'/bootstrap.php';if(!empty($_SESSION['user'])){header('Location: '.url('dashboard.php'));exit;}$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$st=$pdo->prepare("SELECT id,company_id,name,email,password_hash,role FROM users WHERE email=? AND status='active' LIMIT 1");$st->execute([strtolower(trim($_POST['email']??''))]);$u=$st->fetch();if($u&&password_verify($_POST['password']??'',$u['password_hash'])){session_regenerate_id(true);unset($u['password_hash']);$_SESSION['user']=$u;$pdo->prepare('UPDATE users SET last_login_at=NOW() WHERE id=?')->execute([$u['id']]);header('Location: '.url('dashboard.php'));exit;}$error='E-mail ou senha incorretos.';}
?><!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width"><title>Área do Cliente | Newsiga</title><link rel="stylesheet" href="assets/style.css"><style>.password-wrap{position:relative;width:100%}.password-wrap input{display:block;width:100%;padding-right:54px}.password-toggle{position:absolute;right:3px;top:3px;width:42px;height:42px;display:grid;place-items:center;border:0;background:transparent;color:#52675f;cursor:pointer;border-radius:4px}.password-toggle:hover,.password-toggle:focus-visible{color:#0c2a23;background:#f2f4ef;outline:2px solid #9baba4;outline-offset:-2px}.password-toggle svg{width:22px;height:22px;fill:none;stroke:currentColor;stroke-width:1.8;stroke-linecap:round;stroke-linejoin:round}.password-toggle .eye-off{display:none}.password-toggle[aria-pressed="true"] .eye-on{display:none}.password-toggle[aria-pressed="true"] .eye-off{display:block}</style></head><body class="login-bg"><main class="login-card"><a class="brand" href="/">newsiga</a><p class="kicker">ÁREA DO CLIENTE</p><h1>Bem-vindo ao portal Newsiga</h1><p>Acompanhe seus contratos e chamados.</p><?php if($error):?><p class="error"><?=e($error)?></p><?php endif;?><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><label>E-mail corporativo<input name="email" type="email" required autocomplete="username"></label><label>Senha<div class="password-wrap"><input id="loginPassword" name="password" type="password" required autocomplete="current-password"><button class="password-toggle" type="button" aria-label="Mostrar senha" aria-pressed="false" title="Mostrar senha" onclick="togglePassword(this)"><svg class="eye-on" viewBox="0 0 24 24" aria-hidden="true"><path d="M2.5 12s3.5-6 9.5-6 9.5 6 9.5 6-3.5 6-9.5 6-9.5-6-9.5-6Z"/><circle cx="12" cy="12" r="2.7"/></svg><svg class="eye-off" viewBox="0 0 24 24" aria-hidden="true"><path d="M3 3l18 18"/><path d="M10.6 6.2A10.9 10.9 0 0 1 12 6c6 0 9.5 6 9.5 6a17 17 0 0 1-2.2 2.8M6.2 6.2C3.8 7.8 2.5 12 2.5 12s3.5 6 9.5 6a9.8 9.8 0 0 0 4-.8M9.9 9.9a3 3 0 0 0 4.2 4.2"/></svg></button></div></label><button class="button">Entrar no portal</button></form><a class="login-help" href="<?=url('esqueci-a-senha.php')?>">Esqueci minha senha</a></main><script>function togglePassword(button){const input=document.getElementById('loginPassword');const show=input.type==='password';input.type=show?'text':'password';button.setAttribute('aria-pressed',show?'true':'false');button.setAttribute('aria-label',show?'Ocultar senha':'Mostrar senha');button.setAttribute('title',show?'Ocultar senha':'Mostrar senha')}</script></body></html>
